// domain module build.gradle.kts — no Android plugin applied
plugins { kotlin("jvm") } // pure Kotlin, no android.* imports possible

class GetUserUseCase(private val repository: UserRepository) {
    suspend operator fun invoke(id: String): User = repository.getUser(id)
}

class PlaceOrderUseCase(
    private val orders: OrderRepository,
    private val clock: Clock
) {
    suspend operator fun invoke(cart: Cart): Result<Order> {
        if (cart.items.isEmpty()) return Result.failure(EmptyCartException())
        return runCatching { orders.place(cart, placedAt = clock.now()) }
    }
}

