// data layer
fun UserDto.toDomain() = User(id = id, name = fullName, isPremium = tier == "premium")
fun UserEntity.toDomain() = User(id = id, name = name, isPremium = premium)

// presentation layer
fun User.toUi() = UserUi(title = name, badge = if (isPremium) "PRO" else null)

class ArticleRepository(private val api: ArticleApi, private val dao: ArticleDao) {
    // The UI only ever observes the database
    fun observeArticles(): Flow<List<Article>> =
        dao.observeAll().map { rows -> rows.map { it.toDomain() } }

    // Network -> database; the Flow above re-emits automatically
    suspend fun refresh() {
        val fresh = api.fetchArticles().map { it.toEntity() }
        dao.replaceAll(fresh)
    }
}

class UserRemoteDataSource(private val api: UserApi) {
    suspend fun fetch(id: String): UserDto = api.getUser(id)          // one source, raw data
}

class UserLocalDataSource(private val dao: UserDao) {
    fun observe(id: String): Flow<UserEntity?> = dao.observe(id)
    suspend fun save(user: UserEntity) = dao.upsert(user)
}

class UserRepositoryImpl(
    private val remote: UserRemoteDataSource,
    private val local: UserLocalDataSource
) : UserRepository {
    override fun observeUser(id: String): Flow<User?> = local.observe(id).map { it?.toDomain() }
    override suspend fun refresh(id: String) = local.save(remote.fetch(id).toEntity())   // policy
}

// domain module: knows nothing about Retrofit or Room
interface UserRepository {
    fun observeUser(id: String): Flow<User?>
}

// data module: implements the domain's interface
